import React from 'react';
import { TrendingUp } from 'lucide-react';

/**
 * Günlük Canlı Ağırlık Artışı (ADG / GCAA) Hesaplayıcı & Büyüme Performans Kartı
 * Hayvanın doğumundan veya son tartımından bu yana günlük kazandığı gram/kg miktarını gösterir.
 */
export default function GrowthRateCard({ animal }) {
  if (!animal || !animal.birth_date || !animal.current_weight) {
    return null;
  }

  const birthDate = new Date(animal.birth_date);
  const now = new Date();
  const ageInDays = Math.max(1, Math.floor((now - birthDate) / (1000 * 60 * 60 * 24)));

  // Doğum ağırlığı tahmini (varsayılan: buzağı 40kg, kuzu/oğlak 3.5kg)
  const isCattle = animal.species === 'Sığır' || animal.species === 'Manda';
  const estimatedBirthWeight = isCattle ? 38 : 3.5;

  const totalGain = Math.max(0, animal.current_weight - estimatedBirthWeight);
  const adgGrams = Math.round((totalGain / ageInDays) * 1000); // Gram / gün
  const adgKg = (adgGrams / 1000).toFixed(2);

  // Performans değerlendirmesi
  let rating = 'Normal';
  let badgeClass = 'bg-blue-100 text-blue-800';
  if (isCattle) {
    if (adgGrams >= 1100) { rating = 'Mükemmel Besi'; badgeClass = 'bg-emerald-100 text-emerald-800'; }
    else if (adgGrams >= 800) { rating = 'İyi Gelişim'; badgeClass = 'bg-teal-100 text-teal-800'; }
    else { rating = 'Yavaş Gelişim'; badgeClass = 'bg-amber-100 text-amber-800'; }
  } else {
    if (adgGrams >= 250) { rating = 'Mükemmel Besi'; badgeClass = 'bg-emerald-100 text-emerald-800'; }
    else if (adgGrams >= 180) { rating = 'İyi Gelişim'; badgeClass = 'bg-teal-100 text-teal-800'; }
    else { rating = 'Yavaş Gelişim'; badgeClass = 'bg-amber-100 text-amber-800'; }
  }

  return (
    <div className="card p-4 bg-white border border-gray-100 shadow-xs rounded-2xl animate-in fade-in">
      <div className="flex items-center justify-between mb-3">
        <div className="flex items-center gap-2">
          <div className="p-2 bg-emerald-50 text-emerald-700 rounded-xl">
            <TrendingUp className="w-4 h-4" />
          </div>
          <div>
            <h4 className="font-bold text-gray-900 text-xs uppercase tracking-wider">
              Büyüme Hızı (ADG / GCAA)
            </h4>
            <p className="text-[11px] text-gray-400">Günlük canlı ağırlık artış endeksi</p>
          </div>
        </div>
        <span className={`px-2.5 py-0.5 rounded-full text-[10px] font-black uppercase ${badgeClass}`}>
          {rating}
        </span>
      </div>

      <div className="grid grid-cols-3 gap-2 text-center bg-gray-50/70 p-3 rounded-xl">
        <div>
          <p className="text-[10px] text-gray-400 font-bold uppercase">Mevcut Ağırlık</p>
          <p className="text-sm font-black text-gray-800 mt-0.5">{animal.current_weight} kg</p>
        </div>
        <div>
          <p className="text-[10px] text-gray-400 font-bold uppercase">Yaş (Gün)</p>
          <p className="text-sm font-black text-gray-800 mt-0.5">{ageInDays} gün</p>
        </div>
        <div>
          <p className="text-[10px] text-gray-400 font-bold uppercase">Günlük Artış</p>
          <p className="text-sm font-black text-emerald-600 mt-0.5">+{adgGrams} g/gün</p>
          <p className="text-[10px] text-emerald-700/70 font-semibold">({adgKg} kg/gün)</p>
        </div>
      </div>
    </div>
  );
}
