import React, { useState } from 'react';
import { Tag, Copy, Check, X, MessageCircle } from 'lucide-react';
import toast from 'react-hot-toast';

/**
 * Canlı Hayvan Satış & Pazar Yeri İlan Kartı (Ultra-Modern Edition)
 * Sosyal medya ve WhatsApp hayvan pazarı grupları için profesyonel ilan künyesi üretir.
 */

export default function MarketplaceCardModal({ isOpen, onClose, animal = {} }) {
  const [price, setPrice] = useState('95000');
  const [sellerPhone, setSellerPhone] = useState('0532 000 00 00');
  const [description, setDescription] = useState('Yüksek süt verimli damızlık gebe düve, tüm karma aşıları tam, resmi TÜRKVET kayıtlı.');
  const [copied, setCopied] = useState(false);

  if (!isOpen) return null;

  const adText = `🐮 *SATILIK DAMIZLIK / BESİ HAYVANI İLANI*
🏷️ *Küpe No:* ${animal.code || 'TR16-00482'}
📌 *Adı:* ${animal.name || 'Sarıkız'}
🧬 *Irk / Tür:* ${animal.species || 'Sığır'} — ${animal.breed || 'Siyah Alaca Holstein'}
⚖️ *Canlı Ağırlık:* ${animal.current_weight || 540} kg
♀ *Cinsiyet:* ${animal.gender === 'F' ? 'Dişi' : 'Erkek'}
💉 *Aşı / Sağlık:* Tam, TÜRKVET ve e-Islah sistemine kayıtlı

💰 *Fiyat:* ₺${parseFloat(price || 0).toLocaleString('tr-TR')} (Pazarlık payı vardır)
📍 *Konum:* mFk Farm Tesisleri
📞 *İletişim:* ${sellerPhone}

📝 *Açıklama:* ${description}
_mFk Farm Doğrulanmış Çiftlik Kayıt Belgesi_`;

  const handleCopy = () => {
    navigator.clipboard.writeText(adText);
    setCopied(true);
    toast.success('İlan künyesi panoya kopyalandı!');
    setTimeout(() => setCopied(false), 2500);
  };

  const handleWhatsAppShare = () => {
    const encoded = encodeURIComponent(adText);
    window.open(`https://api.whatsapp.com/send?text=${encoded}`, '_blank');
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-3 sm:p-4 bg-slate-950/70 backdrop-blur-md animate-fade-in">
      <div className="bg-white w-full max-w-md rounded-3xl shadow-2xl overflow-hidden border border-slate-100 flex flex-col max-h-[92vh]">
        {/* Üst Başlık */}
        <div 
          className="p-5 text-white relative overflow-hidden"
          style={{ background: 'linear-gradient(135deg, #022c22 0%, #064e3b 50%, #0f172a 100%)' }}
        >
          <div className="absolute -right-8 -top-8 w-40 h-40 bg-amber-400/10 rounded-full blur-2xl pointer-events-none" />
          
          <div className="flex items-center justify-between relative z-10">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 rounded-2xl bg-white/10 backdrop-blur-md border border-white/20 flex items-center justify-center shadow-inner">
                <Tag className="w-5 h-5 text-amber-300" />
              </div>
              <div>
                <div className="flex items-center gap-1.5">
                  <h3 className="font-black text-sm text-white tracking-tight">Pazar Yeri İlan Kartı</h3>
                  <span className="px-1.5 py-0.2 rounded-full text-[9px] font-black bg-amber-400/20 text-amber-300 border border-amber-400/30">
                    SATIŞ İLANI
                  </span>
                </div>
                <p className="text-[11px] text-emerald-100/80 mt-0.5">WhatsApp ve pazar grupları için profesyonel format</p>
              </div>
            </div>

            <button 
              onClick={onClose} 
              className="w-8 h-8 rounded-full bg-white/10 hover:bg-white/20 text-white/80 hover:text-white flex items-center justify-center transition-all"
            >
              <X className="w-4 h-4" />
            </button>
          </div>
        </div>

        {/* Form ve Önizleme */}
        <div className="p-4 sm:p-5 space-y-3.5 bg-slate-50/50 flex-1 overflow-y-auto">
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-[11px] font-bold text-gray-700 mb-1">Satış Fiyatı (₺)</label>
              <input
                type="number"
                value={price}
                onChange={(e) => setPrice(e.target.value)}
                className="w-full text-xs font-black border border-gray-200 rounded-xl p-2.5 bg-white text-emerald-800 focus:outline-none focus:ring-2 focus:ring-emerald-500/20"
              />
            </div>
            <div>
              <label className="block text-[11px] font-bold text-gray-700 mb-1">İletişim Telefonu</label>
              <input
                type="text"
                value={sellerPhone}
                onChange={(e) => setSellerPhone(e.target.value)}
                className="w-full text-xs font-medium border border-gray-200 rounded-xl p-2.5 bg-white focus:outline-none focus:ring-2 focus:ring-emerald-500/20"
              />
            </div>
          </div>

          <div>
            <label className="block text-[11px] font-bold text-gray-700 mb-1">İlan Açıklaması</label>
            <textarea
              rows={2}
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              className="w-full text-xs font-medium border border-gray-200 rounded-xl p-2.5 bg-white focus:outline-none focus:ring-2 focus:ring-emerald-500/20 resize-none"
            />
          </div>

          {/* İlan Önizleme Kartı */}
          <div>
            <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1">
              İlan Önizlemesi
            </label>
            <div className="bg-white border border-gray-200 rounded-2xl p-3.5 text-xs font-mono whitespace-pre-line text-gray-800 max-h-44 overflow-y-auto leading-relaxed shadow-inner">
              {adText}
            </div>
          </div>
        </div>

        {/* Alt Eylemler */}
        <div className="p-4 bg-white border-t border-gray-100 flex items-center gap-2">
          <button
            onClick={handleCopy}
            className="flex-1 py-2.5 px-3 rounded-2xl border border-gray-200 bg-gray-50 hover:bg-gray-100 text-gray-700 font-bold text-xs flex items-center justify-center gap-1.5 transition-all"
          >
            {copied ? <Check className="w-3.5 h-3.5 text-emerald-600" /> : <Copy className="w-3.5 h-3.5" />}
            {copied ? 'Kopyalandı' : 'Metni Kopyala'}
          </button>

          <button
            onClick={handleWhatsAppShare}
            className="flex-1 py-2.5 px-3 rounded-2xl bg-emerald-600 hover:bg-emerald-500 text-white font-bold text-xs flex items-center justify-center gap-1.5 transition-all shadow-md shadow-emerald-600/20 active:scale-98"
          >
            <MessageCircle className="w-3.5 h-3.5" />
            WhatsApp'ta Paylaş
          </button>
        </div>
      </div>
    </div>
  );
}
