import React, { useState } from 'react';
import { Shield, Download, X } from 'lucide-react';
import toast from 'react-hot-toast';

/**
 * Hayvan Sigortası & TARSİM Hasar Tazminat Dosyası (Ultra-Modern Edition)
 * Devlet Destekli Tarım Sigortaları (TARSİM) hasar ihbarı ve eksper tazminat dosyası üreticisi.
 */

export default function TarsimInsuranceModal({ isOpen, onClose, animal = {} }) {
  const [policyNo, setPolicyNo] = useState('TRSM-2026-94812');
  const [claimType, setClaimType] = useState('Ölüm / İtlaf');
  const [lossReason, setLossReason] = useState('Doğum Komplikasyonu / Uterus Yırtılması');
  const [estimatedValue, setEstimatedValue] = useState('85000');
  const [veterinarian, setVeterinarian] = useState('Vet. Hekim Serdar K.');

  if (!isOpen) return null;

  const handleDownloadClaim = () => {
    const claimDoc = `=====================================================
T.C. DEVLET DESTEKLİ TARIM SİGORTALARI HAVUZU (TARSİM)
BÜYÜKBAŞ / KÜÇÜKBAŞ HAYVAN HAYAT SİGORTASI HASAR İHBAR FORMU
=====================================================

POLİÇE BİLGİLERİ:
• Poliçe No: ${policyNo}
• Sigortalı İşletme: mFk Farm Hayvancılık İşletmesi
• İhbar Tarihi: ${new Date().toLocaleDateString('tr-TR')}

HAYVAN KİMLİK BİLGİLERİ:
• Küpe No: ${animal.code || 'TR16-00482'}
• Hayvan Adı: ${animal.name || 'Sarıkız'}
• Türü / Irkı: ${animal.species || 'Sığır'} / ${animal.breed || 'Holstein'}
• Cinsiyeti: ${animal.gender === 'F' ? 'Dişi' : 'Erkek'}
• Mevcut Canlı Ağırlık: ${animal.current_weight || 580} kg

HASAR / TAZMİNAT DETAYLARI:
• Hasar Türü: ${claimType}
• Tespit Edilen Neden: ${lossReason}
• Sigorta Bedeli / Talep Edilen Tazminat: ₺${parseFloat(estimatedValue).toLocaleString('tr-TR')}
• Otopsi / Teşhis Yapan Veteriner Hekim: ${veterinarian}

EKLER:
[x] Kulak küpesi ile çekilmiş hayvan fotoğrafları
[x] Veteriner Hekim Otopsi ve İmha Raporu
[x] TÜRKVET Sisteminden Düşüm / Ölüm Belgesi

Eksper Atama Çağrı Merkezi: 0850 250 82 77
Form oluşturulma zamanı: ${new Date().toISOString()}
=====================================================`;

    const blob = new Blob([claimDoc], { type: 'text/plain;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `TARSIM_Hasar_Dosyasi_${animal.code || 'Hayvan'}.txt`;
    a.click();
    toast.success('TARSİM hasar tazminat dosyası hazırlandı ve indirildi!');
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-3 sm:p-4 bg-slate-950/70 backdrop-blur-md animate-fade-in">
      <div className="bg-white w-full max-w-md rounded-3xl shadow-2xl overflow-hidden border border-slate-100 flex flex-col">
        {/* Üst Başlık */}
        <div 
          className="p-5 text-white relative overflow-hidden"
          style={{ background: 'linear-gradient(135deg, #0f172a 0%, #1e3a8a 50%, #0369a1 100%)' }}
        >
          <div className="absolute -right-8 -top-8 w-40 h-40 bg-blue-400/10 rounded-full blur-2xl pointer-events-none" />
          
          <div className="flex items-center justify-between relative z-10">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 rounded-2xl bg-white/10 backdrop-blur-md border border-white/20 flex items-center justify-center shadow-inner">
                <Shield className="w-5 h-5 text-blue-300" />
              </div>
              <div>
                <div className="flex items-center gap-1.5">
                  <h3 className="font-black text-sm text-white tracking-tight">TARSİM Hasar Tazminatı</h3>
                  <span className="px-1.5 py-0.2 rounded-full text-[9px] font-black bg-blue-400/20 text-blue-300 border border-blue-400/30">
                    SİGORTA
                  </span>
                </div>
                <p className="text-[11px] text-blue-100/80 mt-0.5">Resmi eksper ve tazminat dosya hazırlığı</p>
              </div>
            </div>

            <button 
              onClick={onClose} 
              className="w-8 h-8 rounded-full bg-white/10 hover:bg-white/20 text-white/80 hover:text-white flex items-center justify-center transition-all"
            >
              <X className="w-4 h-4" />
            </button>
          </div>
        </div>

        {/* Form Alanı */}
        <div className="p-5 space-y-3.5 bg-slate-50/50">
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-[11px] font-bold text-gray-700 mb-1">TARSİM Poliçe No</label>
              <input
                type="text"
                value={policyNo}
                onChange={(e) => setPolicyNo(e.target.value)}
                className="w-full text-xs font-mono font-bold border border-gray-200 rounded-xl p-2.5 bg-white focus:outline-none focus:ring-2 focus:ring-blue-500/20"
              />
            </div>
            <div>
              <label className="block text-[11px] font-bold text-gray-700 mb-1">Hasar Türü</label>
              <select
                value={claimType}
                onChange={(e) => setClaimType(e.target.value)}
                className="w-full text-xs border border-gray-200 rounded-xl p-2.5 bg-white font-medium focus:outline-none focus:ring-2 focus:ring-blue-500/20"
              >
                <option>Ölüm / İtlaf</option>
                <option>Mecburi Kesim (Acil)</option>
                <option>Yavru Atma (Abortus)</option>
                <option>Sakatlık / Verim Kaybı</option>
              </select>
            </div>
          </div>

          <div>
            <label className="block text-[11px] font-bold text-gray-700 mb-1">Hasar / Ölüm Nedeni</label>
            <input
              type="text"
              value={lossReason}
              onChange={(e) => setLossReason(e.target.value)}
              className="w-full text-xs border border-gray-200 rounded-xl p-2.5 bg-white focus:outline-none focus:ring-2 focus:ring-blue-500/20 font-medium"
            />
          </div>

          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-[11px] font-bold text-gray-700 mb-1">Talep Edilen Bedel (₺)</label>
              <input
                type="number"
                value={estimatedValue}
                onChange={(e) => setEstimatedValue(e.target.value)}
                className="w-full text-xs font-black border border-gray-200 rounded-xl p-2.5 bg-white text-blue-800 focus:outline-none focus:ring-2 focus:ring-blue-500/20"
              />
            </div>
            <div>
              <label className="block text-[11px] font-bold text-gray-700 mb-1">Teşhis Yapan Veteriner</label>
              <input
                type="text"
                value={veterinarian}
                onChange={(e) => setVeterinarian(e.target.value)}
                className="w-full text-xs border border-gray-200 rounded-xl p-2.5 bg-white focus:outline-none focus:ring-2 focus:ring-blue-500/20 font-medium"
              />
            </div>
          </div>

          {/* Hayvan Özet Şeridi */}
          <div className="p-3 bg-blue-50/70 border border-blue-100 rounded-2xl flex items-center justify-between text-xs">
            <div>
              <span className="font-bold text-blue-950">{animal.name || 'Seçili Hayvan'}</span>
              <p className="text-[10px] text-blue-700 font-mono">{animal.code || 'TR-KÜPE'}</p>
            </div>
            <span className="text-[11px] font-bold text-blue-800">
              Canlı: {animal.current_weight || 580} kg
            </span>
          </div>
        </div>

        {/* Alt Eylemler */}
        <div className="p-4 bg-white border-t border-gray-100 flex items-center gap-2">
          <button
            type="button"
            onClick={onClose}
            className="flex-1 py-2.5 px-3 rounded-2xl border border-gray-200 bg-gray-50 hover:bg-gray-100 text-gray-700 font-bold text-xs transition-all"
          >
            İptal
          </button>
          <button
            type="button"
            onClick={handleDownloadClaim}
            className="flex-1 py-2.5 px-3 rounded-2xl bg-blue-700 hover:bg-blue-600 text-white font-bold text-xs flex items-center justify-center gap-1.5 transition-all shadow-md shadow-blue-700/20 active:scale-98"
          >
            <Download className="w-3.5 h-3.5" />
            TARSİM Dosyasını İndir
          </button>
        </div>
      </div>
    </div>
  );
}
