import React, { useRef } from 'react';
import { QrCode, Printer, X, Copy, Check, Sparkles } from 'lucide-react';
import toast from 'react-hot-toast';

/**
 * QR Kod Küpe & Padok Etiket Yazdırıcı Modalı (Ultra-Modern iOS Edition)
 * Her hayvan ve padok için taranabilir resmi QR küpe/kapı etiketi üretir.
 */
export default function QRCodeModal({ isOpen, onClose, animal }) {
  const printRef = useRef(null);
  const [copied, setCopied] = React.useState(false);

  if (!isOpen || !animal) return null;

  const currentUrl = typeof window !== 'undefined' ? `${window.location.origin}/animals/${animal.id}` : '';
  const qrImageUrl = `https://api.qrserver.com/v1/create-qr-code/?size=250x250&data=${encodeURIComponent(currentUrl)}&margin=4`;

  const handlePrint = () => {
    window.print();
  };

  const handleCopyLink = () => {
    navigator.clipboard.writeText(currentUrl);
    setCopied(true);
    toast.success('Hayvan dijital pasaport bağlantısı kopyalandı!');
    setTimeout(() => setCopied(false), 2500);
  };

  return (
    <div className="fixed inset-0 bg-slate-950/70 backdrop-blur-md z-50 flex items-center justify-center p-3 sm:p-4 animate-fade-in">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-sm overflow-hidden border border-slate-100 flex flex-col">
        {/* Üst Yönetici Başlık */}
        <div 
          className="p-5 text-white relative overflow-hidden"
          style={{ background: 'linear-gradient(135deg, #022c22 0%, #064e3b 50%, #0f172a 100%)' }}
        >
          <div className="absolute -right-8 -top-8 w-40 h-40 bg-teal-400/10 rounded-full blur-2xl pointer-events-none" />
          
          <div className="flex items-center justify-between relative z-10">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 rounded-2xl bg-white/10 backdrop-blur-md border border-white/20 flex items-center justify-center shadow-inner">
                <QrCode className="w-5 h-5 text-teal-300" />
              </div>
              <div>
                <div className="flex items-center gap-1.5">
                  <h3 className="font-black text-sm text-white tracking-tight">Dinamik QR Künye</h3>
                  <span className="px-1.5 py-0.2 rounded-full text-[9px] font-black bg-teal-400/20 text-teal-300 border border-teal-400/30">
                    PASAPORT
                  </span>
                </div>
                <p className="text-[11px] text-teal-100/80 mt-0.5">Kamera ile hızlı hayvan profili erişimi</p>
              </div>
            </div>

            <button 
              onClick={onClose} 
              className="w-8 h-8 rounded-full bg-white/10 hover:bg-white/20 text-white/80 hover:text-white flex items-center justify-center transition-all"
            >
              <X className="w-4 h-4" />
            </button>
          </div>
        </div>

        {/* Yazdırılabilir Kart Alanı */}
        <div className="p-5 text-center space-y-4 bg-slate-50/60" ref={printRef}>
          <div className="p-5 border border-slate-200/80 rounded-3xl bg-white shadow-sm inline-block w-full max-w-xs">
            <div className="p-3 bg-slate-50 rounded-2xl inline-block border border-slate-100 shadow-inner mb-3">
              <img 
                src={qrImageUrl} 
                alt={`QR Code ${animal.code}`} 
                className="w-44 h-44 mx-auto rounded-xl object-contain bg-white p-1" 
              />
            </div>

            <div className="space-y-1">
              <span className="inline-block px-3 py-1 bg-teal-50 border border-teal-200 text-teal-900 rounded-full font-mono font-black text-xs tracking-wider">
                {animal.code}
              </span>
              <h4 className="font-bold text-gray-900 text-sm mt-1">
                {animal.name}
              </h4>
              <p className="text-[11px] text-gray-500 font-medium">
                {animal.species} • {animal.breed || 'Safkan'}
              </p>
            </div>

            <div className="mt-3 pt-3 border-t border-gray-100 flex items-center justify-center gap-1.5 text-[10px] text-gray-400">
              <Sparkles className="w-3 h-3 text-teal-600" />
              <span>mFk Farm Akıllı Kimliklendirici</span>
            </div>
          </div>

          <p className="text-xs text-gray-500 leading-relaxed px-3">
            Akıllı telefon kamerası ile tarandığında hayvanın aşı, süt verimi ve soy kütüğü kartını otomatik açar.
          </p>
        </div>

        {/* Alt Eylemler */}
        <div className="p-4 bg-white border-t border-gray-100 flex items-center gap-2">
          <button
            onClick={handleCopyLink}
            className="flex-1 py-2.5 px-3 rounded-2xl border border-gray-200 bg-gray-50 hover:bg-gray-100 text-gray-700 font-bold text-xs flex items-center justify-center gap-1.5 transition-all"
          >
            {copied ? <Check className="w-3.5 h-3.5 text-emerald-600" /> : <Copy className="w-3.5 h-3.5" />}
            {copied ? 'Kopyalandı' : 'Linki Kopyala'}
          </button>

          <button
            onClick={handlePrint}
            className="flex-1 py-2.5 px-3 rounded-2xl bg-teal-700 hover:bg-teal-600 text-white font-bold text-xs flex items-center justify-center gap-1.5 transition-all shadow-md shadow-teal-700/20 active:scale-98"
          >
            <Printer className="w-3.5 h-3.5" />
            Etiketi Yazdır
          </button>
        </div>
      </div>
    </div>
  );
}
